INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-g2-risk-001','exam-sg','リスクマネジメント','standard','single_choice','情報資産のリスク分析で、リスク値を見積もる際の考え方として最も適切なものはどれか。','[{"id":"a","text":"脅威の発生可能性と、発生した場合の影響を組み合わせて評価する。"},{"id":"b","text":"資産の購入価格だけで決める。"},{"id":"c","text":"対策費用が最も高いリスクを最大とする。"},{"id":"d","text":"過去に事故がなければリスクはゼロとする。"}]','"a"','风险通常综合发生可能性与影响程度评估。资产价格、对策成本或过去没有事故，都不能单独代表风险大小。','generated',NULL,'ja'),
('sg-g2-risk-002','exam-sg','リスク対応','standard','single_choice','個人情報を扱う業務のリスクを、保険契約によって第三者へ移転する対応はどれか。','[{"id":"a","text":"リスク回避"},{"id":"b","text":"リスク低減"},{"id":"c","text":"リスク移転"},{"id":"d","text":"リスク保有"}]','"c"','通过保险等安排将部分经济损失转由第三方承担，属于风险转移。风险本身不一定消失。','generated',NULL,'ja'),
('sg-g2-governance-001','exam-sg','情報セキュリティ管理','standard','single_choice','情報セキュリティ方針を組織全体に定着させるために、経営層が最初に行うべきこととして最も適切なものはどれか。','[{"id":"a","text":"担当者だけに責任を任せ、経営層は関与しない。"},{"id":"b","text":"方針と責任者を明確にし、必要な資源を確保して周知する。"},{"id":"c","text":"事故が発生するまで規則を作らない。"},{"id":"d","text":"全社員に同じ管理者パスワードを配布する。"}]','"b"','信息安全治理需要管理层明确方针、责任和资源，并推动全员知晓与执行；不能只把责任推给技术人员。','generated',NULL,'ja'),
('sg-g2-access-001','exam-sg','アクセス制御','standard','single_choice','退職した従業員が社内システムを利用できないようにするため、最も優先すべき対応はどれか。','[{"id":"a","text":"退職者のアカウントと認証手段を速やかに無効化する。"},{"id":"b","text":"パスワード変更の案内を社内掲示板に掲載する。"},{"id":"c","text":"退職者のメールだけを非表示にする。"},{"id":"d","text":"監査ログを削除する。"}]','"a"','离职后应及时撤销账号、令牌、VPN 等访问权限，避免权限残留。仅隐藏邮件或删除日志不能阻止访问。','generated',NULL,'ja'),
('sg-g2-auth-001','exam-sg','認証','standard','single_choice','多要素認証（MFA）の説明として最も適切なものはどれか。','[{"id":"a","text":"パスワードを2回入力させる方式"},{"id":"b","text":"異なる種類の認証要素を2つ以上組み合わせる方式"},{"id":"c","text":"複数のサービスで同じパスワードを使う方式"},{"id":"d","text":"利用者名を暗号化する方式"}]','"b"','MFA 是组合不同类别的认证因素，例如“知道的密码”与“持有的安全密钥”。同一密码输入两次不属于多因素认证。','generated',NULL,'ja'),
('sg-g2-phishing-001','exam-sg','インシデント対応','standard','single_choice','従業員が不審なメールの添付ファイルを開いた可能性がある。最も適切な初動はどれか。','[{"id":"a","text":"証拠を残さず、端末内のファイルをすべて削除する。"},{"id":"b","text":"上司や所定の窓口へ速やかに報告し、指示に従って端末を隔離する。"},{"id":"c","text":"同じ添付ファイルを同僚へ転送して確認する。"},{"id":"d","text":"何も起きていないように見えるので放置する。"}]','"b"','应尽快报告并按事件响应流程隔离设备，减少扩散；不要转发可疑附件或擅自破坏证据。','generated',NULL,'ja'),
('sg-g2-incident-002','exam-sg','インシデント対応','standard','single_choice','情報漏えいの疑いがある場合、原因調査と被害拡大防止を両立するために重要なことはどれか。','[{"id":"a","text":"関係するログを保全し、定められた対応体制で事実を確認する。"},{"id":"b","text":"調査開始前にすべてのログを消去する。"},{"id":"c","text":"原因が確定するまで誰にも報告しない。"},{"id":"d","text":"関係者全員の個人端末を無断で初期化する。"}]','"a"','日志保全有助于还原时间线和确定影响范围；应依照既定流程报告、调查和控制损害。','generated',NULL,'ja'),
('sg-g2-backup-001','exam-sg','バックアップ','standard','single_choice','ランサムウェアによる被害に備えるバックアップ運用として、最も適切なものはどれか。','[{"id":"a","text":"バックアップを常に本番端末に接続したままにする。"},{"id":"b","text":"バックアップの取得だけ行い、復元試験はしない。"},{"id":"c","text":"本番環境から分離したバックアップを保持し、定期的に復元を試験する。"},{"id":"d","text":"バックアップ先にも本番と同じ管理者パスワードを共有する。"}]','"c"','备份应尽可能与生产环境隔离，并定期进行恢复测试。仅有备份文件而无法恢复，不能满足业务连续性要求。','generated',NULL,'ja'),
('sg-g2-crypto-001','exam-sg','暗号技術','standard','single_choice','公開鍵暗号方式で、送信者が受信者だけに読めるメッセージを送る場合、通常どの鍵で暗号化するか。','[{"id":"a","text":"送信者の秘密鍵"},{"id":"b","text":"受信者の公開鍵"},{"id":"c","text":"受信者の秘密鍵を送信者へ渡して使う"},{"id":"d","text":"誰でも知っている共通の秘密鍵"}]','"b"','机密性を確保するには受信者の公开鍵加密，受信者用自己的私钥解密。私钥不能传给发送者。','generated',NULL,'ja'),
('sg-g2-hash-001','exam-sg','ハッシュ','standard','single_choice','パスワードをデータベースに保存する方法として、最も適切なものはどれか。','[{"id":"a","text":"平文のまま保存する。"},{"id":"b","text":"復号可能な暗号化だけを行い、鍵を同じ表に保存する。"},{"id":"c","text":"ソルトを付け、計算コストの高いパスワードハッシュ関数で保存する。"},{"id":"d","text":"すべての利用者に同じ固定ハッシュ値を割り当てる。"}]','"c"','密码应使用专门的密码哈希算法并加盐保存，例如 Argon2id、scrypt 或适当配置的 bcrypt。普通可逆加密或明文保存风险很高。','generated',NULL,'ja'),
('sg-g2-patch-001','exam-sg','脆弱性管理','standard','single_choice','重要なサーバに深刻な脆弱性が公表された。修正プログラムを適用する前に必要な対応として最も適切なものはどれか。','[{"id":"a","text":"影響を確認せず、すべての本番サーバへ即時に適用する。"},{"id":"b","text":"資産と影響範囲を確認し、緊急度を評価して検証・適用計画を立てる。"},{"id":"c","text":"脆弱性情報を無視し、次年度まで待つ。"},{"id":"d","text":"脆弱性の存在を隠すために監視を停止する。"}]','"b"','需要结合资产、暴露面、利用可能的攻击方式和业务影响评估优先级，并在可行范围内测试、部署及验证修复。紧急情况下应按应急流程加速。','generated',NULL,'ja'),
('sg-g2-logging-001','exam-sg','ログ管理','standard','single_choice','不正アクセスの調査に役立つログ管理として、最も適切なものはどれか。','[{"id":"a","text":"管理者でも自由に変更・削除できる場所にだけ保存する。"},{"id":"b","text":"時刻を同期し、アクセス制御と改ざん防止を考慮して保管する。"},{"id":"c","text":"容量を節約するため、毎日すべて削除する。"},{"id":"d","text":"ログには個人情報が含まれる可能性があるため、一切取得しない。"}]','"b"','时间同步便于关联不同系统事件；严格访问控制、保留期限和防篡改措施可提升日志调查价值。日志也应遵循隐私和最小化原则。','generated',NULL,'ja'),
('sg-g2-cloud-001','exam-sg','クラウドサービス管理','standard','single_choice','クラウドサービスを利用する際の責任分界について、最も適切な説明はどれか。','[{"id":"a","text":"クラウドを使えば、利用者側のセキュリティ管理は不要になる。"},{"id":"b","text":"責任範囲はサービス形態や契約によって異なるため、事前に確認する。"},{"id":"c","text":"すべてのセキュリティ責任は必ず提供事業者だけが負う。"},{"id":"d","text":"契約内容より広告の説明を優先する。"}]','"b"','云服务的责任边界会因 IaaS、PaaS、SaaS 和合同而异。使用方仍可能负责账号、数据、权限配置、终端和合规等事项。','generated',NULL,'ja'),
('sg-g2-vendor-001','exam-sg','委託先管理','standard','single_choice','個人情報の処理を外部事業者へ委託する前に、最も適切に行うべきことはどれか。','[{"id":"a","text":"委託先の安全管理措置、契約上の責任、事故報告方法を確認する。"},{"id":"b","text":"委託した時点で自社の責任はすべてなくなる。"},{"id":"c","text":"委託先の選定後は監督も確認も不要とする。"},{"id":"d","text":"業務に不要な個人情報もすべて渡す。"}]','"a"','委托前应评估供应商安全能力，在合同中明确处理范围、保护措施、事故报告和再委托等要求，并持续监督。','generated',NULL,'ja'),
('sg-g2-change-001','exam-sg','変更管理','standard','single_choice','業務システムの本番変更を安全に実施するための手順として、最も適切なものはどれか。','[{"id":"a","text":"担当者の判断だけで、記録を残さず変更する。"},{"id":"b","text":"変更内容、影響、承認、試験、切戻し手順を確認して実施する。"},{"id":"c","text":"障害が起きても戻せないよう、旧版をすべて削除する。"},{"id":"d","text":"変更後の動作確認を省略する。"}]','"b"','变更管理应包括影响评估、审批、测试、实施记录、验证和回退方案，以降低变更导致的故障或安全问题。','generated',NULL,'ja'),
('sg-g2-privacy-001','exam-sg','個人情報保護','standard','single_choice','業務上の目的に必要な範囲を超えて個人情報を収集しないという考え方に最も近いものはどれか。','[{"id":"a","text":"データ最小化"},{"id":"b","text":"職務分離"},{"id":"c","text":"負荷分散"},{"id":"d","text":"多重化"}]','"a"','数据最小化强调只收集、使用和保留完成明确目的所必需的数据，减少泄露风险和管理成本。','generated',NULL,'ja'),
('sg-g2-bcp-001','exam-sg','事業継続管理','standard','single_choice','重要業務の停止に備えて、目標復旧時間（RTO）を定める目的として最も適切なものはどれか。','[{"id":"a","text":"許容できる復旧までの時間目標を明確にする。"},{"id":"b","text":"バックアップの暗号鍵を公開する。"},{"id":"c","text":"すべての障害を完全に防止できると保証する。"},{"id":"d","text":"システムの利用者数を増やす。"}]','"a"','RTO（恢复时间目标）用于明确业务或系统中断后，期望在多长时间内恢复。它不是保证绝不发生故障，也不同于 RPO。','generated',NULL,'ja'),
('sg-g2-separation-001','exam-sg','職務分離','standard','single_choice','不正や誤操作を抑止するため、支払データの作成者と承認者を分ける統制はどれか。','[{"id":"a","text":"職務分離"},{"id":"b","text":"シングルサインオン"},{"id":"c","text":"データ圧縮"},{"id":"d","text":"負荷テスト"}]','"a"','将关键操作拆分给不同人员执行与审批，属于职责分离，可降低单人舞弊或错误未被发现的风险。','generated',NULL,'ja'),
('sg-g2-social-001','exam-sg','ソーシャルエンジニアリング','standard','single_choice','電話で「システム管理者だ」と名乗る相手から、利用者のパスワードを尋ねられた。最も適切な対応はどれか。','[{"id":"a","text":"緊急だと言われたら、その場で伝える。"},{"id":"b","text":"本人確認をせず、メールでパスワードを送る。"},{"id":"c","text":"パスワードは伝えず、社内の正式な手順で相手を確認・報告する。"},{"id":"d","text":"同僚全員へ自分のパスワードを共有する。"}]','"c"','社会工程学会利用冒充身份、制造紧迫感等方式诱骗信息。不得透露密码，应通过独立可信的正式渠道核实并报告。','generated',NULL,'ja'),
('sg-g2-classification-001','exam-sg','情報資産管理','standard','single_choice','情報資産の分類と取扱いルールを定める主な目的はどれか。','[{"id":"a","text":"すべての情報を同じ方法で公開するため"},{"id":"b","text":"重要度や機密性に応じて適切な保護措置を選ぶため"},{"id":"c","text":"情報の所有者を不明にするため"},{"id":"d","text":"保存期間を必ず無期限にするため"}]','"b"','按重要性和敏感程度分类，才能制定与风险相称的访问、传输、存储、保留和销毁规则。','generated',NULL,'ja'),
('sg-g2-supply-001','exam-sg','サプライチェーンセキュリティ','standard','single_choice','ソフトウェアの供給元に起因するリスクを下げる対策として、最も適切なものはどれか。','[{"id":"a","text":"供給元の評価、更新元の真正性確認、構成情報の管理を行う。"},{"id":"b","text":"出所不明の更新ファイルを優先して適用する。"},{"id":"c","text":"委託先のセキュリティ状況は確認しない。"},{"id":"d","text":"すべての検証記録を削除する。"}]','"a"','供应链安全需要评估供应商、验证软件和更新的来源与完整性，并维护组件清单和漏洞处置流程。','generated',NULL,'ja'),
('sg-g2-awareness-001','exam-sg','教育・訓練','standard','single_choice','情報セキュリティ教育の効果を高める方法として、最も適切なものはどれか。','[{"id":"a","text":"入社時に一度だけ説明し、その後は確認しない。"},{"id":"b","text":"実際の業務リスクに沿った教育を継続し、理解度や行動を確認する。"},{"id":"c","text":"技術部門以外には教育しない。"},{"id":"d","text":"事故の事例を一切共有しない。"}]','"b"','安全教育应持续进行，并结合岗位风险、钓鱼演练、事件复盘等方式检查理解与实际行为，而非仅一次性宣讲。','generated',NULL,'ja');
